CREATE OR REPLACE FUNCTION public.create_group_with_students(p_name text, p_catechist_ids uuid[], p_students jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role          text;
  v_name          text;
  v_group_id      uuid;
  v_count         int;
  v_dupes         text[];
  v_bad_catechist int;
BEGIN
  -- --------------------------------------------------------------- permisos
  SELECT role INTO v_role FROM public.profiles WHERE id = auth.uid();

  IF v_role IS DISTINCT FROM 'coordinator' THEN
    RAISE EXCEPTION 'Solo un coordinador puede crear grupos.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- ----------------------------------------------------- nombre del grupo
  v_name := btrim(coalesce(p_name, ''));

  IF v_name = '' THEN
    RAISE EXCEPTION 'El nombre del grupo es obligatorio.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT (
       v_name LIKE '1º PRECONFIRMACIÓN%'
    OR v_name LIKE '2º PRECONFIRMACIÓN%'
    OR v_name LIKE '1º CONFIRMACIÓN%'
    OR v_name LIKE '2º CONFIRMACIÓN%'
  ) THEN
    RAISE EXCEPTION 'El nombre debe empezar por "1º PRECONFIRMACIÓN", "2º PRECONFIRMACIÓN", "1º CONFIRMACIÓN" o "2º CONFIRMACIÓN". Recibido: "%".', v_name
      USING ERRCODE = 'check_violation';
  END IF;

  -- Comparación sin distinguir mayúsculas para no acabar con "(A)" y "(a)".
  IF EXISTS (SELECT 1 FROM public.groups WHERE upper(btrim(name)) = upper(v_name)) THEN
    RAISE EXCEPTION 'Ya existe un grupo llamado "%".', v_name
      USING ERRCODE = 'unique_violation';
  END IF;

  -- ------------------------------------------------------------- alumnos
  SELECT count(*) INTO v_count FROM jsonb_array_elements(coalesce(p_students, '[]'::jsonb));

  IF v_count = 0 THEN
    RAISE EXCEPTION 'El fichero no contiene ningún alumno.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- DNIs repetidos dentro del propio fichero.
  SELECT array_agg(dni) INTO v_dupes
  FROM (
    SELECT s->>'dni' AS dni
    FROM jsonb_array_elements(p_students) s
    WHERE nullif(btrim(coalesce(s->>'dni', '')), '') IS NOT NULL
    GROUP BY s->>'dni'
    HAVING count(*) > 1
  ) d;

  IF v_dupes IS NOT NULL THEN
    RAISE EXCEPTION 'El fichero tiene DNIs repetidos: %.', array_to_string(v_dupes, ', ')
      USING ERRCODE = 'unique_violation';
  END IF;

  -- DNIs con letra de control incorrecta. El CHECK students_dni_valid ya lo
  -- impediría, pero abortaría con un mensaje genérico sin decir cuáles fallan.
  SELECT array_agg(dni) INTO v_dupes
  FROM (
    SELECT btrim(s->>'dni') AS dni
    FROM jsonb_array_elements(p_students) s
    WHERE nullif(btrim(coalesce(s->>'dni', '')), '') IS NOT NULL
      AND NOT public.is_valid_spanish_dni_nie(btrim(s->>'dni'))
  ) d;

  IF v_dupes IS NOT NULL THEN
    RAISE EXCEPTION 'Estos DNI/NIE no son válidos: %. No se ha importado nada.', array_to_string(v_dupes, ', ')
      USING ERRCODE = 'check_violation';
  END IF;

  -- DNIs que ya existen en la base de datos. Se aborta todo, no se importa a medias.
  SELECT array_agg(DISTINCT st.dni) INTO v_dupes
  FROM public.students st
  WHERE st.dni IS NOT NULL
    AND st.dni IN (
      SELECT btrim(s->>'dni')
      FROM jsonb_array_elements(p_students) s
      WHERE nullif(btrim(coalesce(s->>'dni', '')), '') IS NOT NULL
    );

  IF v_dupes IS NOT NULL THEN
    RAISE EXCEPTION 'Estos DNI ya existen en la base de datos: %. No se ha importado nada.', array_to_string(v_dupes, ', ')
      USING ERRCODE = 'unique_violation';
  END IF;

  -- --------------------------------------------------------- catequistas
  IF p_catechist_ids IS NULL OR array_length(p_catechist_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Debes asignar al menos un catequista al grupo.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT count(*) INTO v_bad_catechist
  FROM unnest(p_catechist_ids) AS cid
  WHERE NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = cid);

  IF v_bad_catechist > 0 THEN
    RAISE EXCEPTION 'Alguno de los catequistas seleccionados no existe.'
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  -- ------------------------------------------------------------- creación
  INSERT INTO public.groups (name) VALUES (v_name) RETURNING id INTO v_group_id;

  INSERT INTO public.group_catechist (group_id, profile_id)
  SELECT v_group_id, cid FROM unnest(p_catechist_ids) AS cid;

  INSERT INTO public.students (name, dni, gender, email, parent_email, school, birth_date, group_id)
  SELECT
    btrim(s->>'name'),
    nullif(btrim(coalesce(s->>'dni', '')), ''),
    nullif(btrim(coalesce(s->>'gender', '')), ''),
    nullif(btrim(coalesce(s->>'email', '')), ''),
    nullif(btrim(coalesce(s->>'parent_email', '')), ''),
    nullif(btrim(coalesce(s->>'school', '')), ''),
    nullif(btrim(coalesce(s->>'birth_date', '')), '')::date,
    v_group_id
  FROM jsonb_array_elements(p_students) s;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'group_id', v_group_id,
    'group_name', v_name,
    'alumnos_creados', v_count,
    'catequistas_asignados', array_length(p_catechist_ids, 1)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_student_public_access()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  insert into public.student_public_access (student_id, public_id)
  values (
    new.id,
    public.generate_unique_student_public_id()
  )
  on conflict (student_id) do nothing;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_birthday_pushes_if_madrid_9am()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  madrid_now timestamp;
begin
  madrid_now := now() at time zone 'Europe/Madrid';

  -- Solo dispara si en Madrid son las 09:xx
  if extract(hour from madrid_now)::int <> 9 then
    return;
  end if;

  perform net.http_post(
    url := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url')
      || '/functions/v1/send-birthday-pushes',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (select decrypted_secret from vault.decrypted_secrets where name = 'birthday_cron_secret')
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 10000
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.force_uppercase_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  col text := TG_ARGV[0];   -- nombre de columna pasado por el trigger
  j   jsonb;
  v   text;
BEGIN
  -- Convertimos NEW a jsonb para poder acceder a la columna por nombre
  j := to_jsonb(NEW);
  v := j ->> col;

  IF v IS NOT NULL THEN
    -- Sobreescribimos la clave 'col' con su versión en mayúsculas
    j := jsonb_set(j, ARRAY[col], to_jsonb(UPPER(v)), false);
    -- Volvemos a convertir a record del tipo de la fila
    NEW := jsonb_populate_record(NEW, j);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_student_public_id()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  chars text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  part1 text := '';
  part2 text := '';
  i int;
  candidate text;
begin
  for i in 1..4 loop
    part1 := part1 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  end loop;

  for i in 1..3 loop
    part2 := part2 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
  end loop;

  candidate := 'SANP-' || part1 || '-' || part2;

  return candidate;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_unique_student_public_id()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  chars text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  part1 text;
  part2 text;
  candidate text;
  exists_already boolean;
begin
  loop
    part1 := '';
    part2 := '';

    for i in 1..4 loop
      part1 := part1 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    end loop;

    for i in 1..3 loop
      part2 := part2 || substr(chars, floor(random() * length(chars) + 1)::int, 1);
    end loop;

    candidate := 'SANP-' || part1 || '-' || part2;

    select exists(
      select 1
      from public.student_public_access
      where public_id = candidate
    )
    into exists_already;

    if not exists_already then
      return candidate;
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_valid_spanish_dni(dni_text text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  clean_dni text;
  number_part bigint;
  letter_part text;
  expected_letter text;
  letters text := 'TRWAGMYFPDXBNJZSQVHLCKE';
BEGIN
  IF dni_text IS NULL OR TRIM(dni_text) = '' THEN
    RETURN true;
  END IF;

  clean_dni := UPPER(TRIM(dni_text));

  -- Solo valida DNI clásico: 8 números + letra
  IF clean_dni !~ '^[0-9]{8}[A-Z]$' THEN
    RETURN false;
  END IF;

  number_part := SUBSTRING(clean_dni FROM 1 FOR 8)::bigint;
  letter_part := SUBSTRING(clean_dni FROM 9 FOR 1);

  expected_letter := SUBSTRING(
    letters
    FROM ((number_part % 23)::integer + 1)
    FOR 1
  );

  RETURN letter_part = expected_letter;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_valid_spanish_dni_nie(doc_text text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  clean_doc text;
  numeric_part text;
  letter_part text;
  expected_letter text;
  letters text := 'TRWAGMYFPDXBNJZSQVHLCKE';
  doc_number bigint;
BEGIN
  IF doc_text IS NULL OR TRIM(doc_text) = '' THEN
    RETURN true;
  END IF;

  clean_doc := UPPER(TRIM(doc_text));

  -- Caso DNI: 8 números + letra
  IF clean_doc ~ '^[0-9]{8}[A-Z]$' THEN
    numeric_part := SUBSTRING(clean_doc FROM 1 FOR 8);
    letter_part := SUBSTRING(clean_doc FROM 9 FOR 1);

    doc_number := numeric_part::bigint;
    expected_letter := SUBSTRING(
      letters
      FROM ((doc_number % 23)::integer + 1)
      FOR 1
    );

    RETURN letter_part = expected_letter;
  END IF;

  -- Caso NIE: X/Y/Z + 7 números + letra
  IF clean_doc ~ '^[XYZ][0-9]{7}[A-Z]$' THEN
    numeric_part :=
      CASE SUBSTRING(clean_doc FROM 1 FOR 1)
        WHEN 'X' THEN '0'
        WHEN 'Y' THEN '1'
        WHEN 'Z' THEN '2'
      END
      || SUBSTRING(clean_doc FROM 2 FOR 7);

    letter_part := SUBSTRING(clean_doc FROM 9 FOR 1);

    doc_number := numeric_part::bigint;
    expected_letter := SUBSTRING(
      letters
      FROM ((doc_number % 23)::integer + 1)
      FOR 1
    );

    RETURN letter_part = expected_letter;
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_students_dni()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.dni IS NOT NULL THEN
    NEW.dni := UPPER(TRIM(NEW.dni));
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.promote_academic_year(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_month              int;
  v_target_year        int;
  v_already            timestamptz;
  v_graduating_groups  uuid[];
  v_graduating_students uuid[];

  v_deleted_attendance int := 0;
  v_deleted_incidents  int := 0;
  v_deleted_services   int := 0;
  v_deleted_tokens     int := 0;
  v_cleared_verif      int := 0;
  v_deleted_access     int := 0;
  v_deleted_students   int := 0;
  v_deleted_links      int := 0;
  v_deleted_groups     int := 0;
  v_renamed            int := 0;
BEGIN
  -- ---------------------------------------------------------------- guardas
  v_month := EXTRACT(MONTH FROM (now() AT TIME ZONE 'Europe/Madrid'))::int;

  IF v_month NOT IN (8, 9, 10) THEN
    RAISE EXCEPTION 'Fuera de plazo: la promoción solo puede hacerse en agosto, septiembre u octubre (mes actual: %).', v_month
      USING ERRCODE = 'check_violation';
  END IF;

  -- En los tres meses permitidos, el curso de destino es siempre el que empieza
  -- este mismo año natural: en agosto de 2026 se promociona al CURSO 26-27.
  v_target_year := EXTRACT(YEAR FROM (now() AT TIME ZONE 'Europe/Madrid'))::int;

  SELECT promoted_at INTO v_already
  FROM public.academic_year_promotions
  WHERE academic_year_start = v_target_year;

  IF v_already IS NOT NULL THEN
    RAISE EXCEPTION 'El curso %-% ya se promocionó el %. No se puede repetir.',
      v_target_year, v_target_year + 1, to_char(v_already AT TIME ZONE 'Europe/Madrid', 'DD/MM/YYYY HH24:MI')
      USING ERRCODE = 'check_violation';
  END IF;

  -- -------------------------------------------------- 1. snapshot (pre-rename)
  SELECT coalesce(array_agg(id), '{}') INTO v_graduating_groups
  FROM public.groups
  WHERE name LIKE '2º CONFIRMACIÓN%';

  SELECT coalesce(array_agg(id), '{}') INTO v_graduating_students
  FROM public.students
  WHERE group_id = ANY (v_graduating_groups);

  -- ------------------------------------------------------- 2. bajas de alumnos
  -- Se borra de hijos a padres para no depender de que existan ON DELETE CASCADE.
  IF array_length(v_graduating_students, 1) > 0 THEN

    -- parent_email_verifications no se borra: la verificación pertenece al email
    -- del padre/madre, que puede seguir teniendo otros hijos en catequesis.
    -- Solo se desvincula del alumno que se da de baja.
    UPDATE public.parent_email_verifications
       SET last_student_id = NULL
     WHERE last_student_id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_cleared_verif = ROW_COUNT;

    DELETE FROM public.parent_email_verification_tokens
     WHERE student_id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_deleted_tokens = ROW_COUNT;

    DELETE FROM public.mass_services
     WHERE student_id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_deleted_services = ROW_COUNT;

    DELETE FROM public.incidents
     WHERE student_id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_deleted_incidents = ROW_COUNT;

    DELETE FROM public.student_attendance
     WHERE student_id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_deleted_attendance = ROW_COUNT;

    DELETE FROM public.student_public_access
     WHERE student_id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_deleted_access = ROW_COUNT;

    DELETE FROM public.students
     WHERE id = ANY (v_graduating_students);
    GET DIAGNOSTICS v_deleted_students = ROW_COUNT;
  END IF;

  -- --------------------------------------------------- 3. grupos ya vaciados
  IF array_length(v_graduating_groups, 1) > 0 THEN
    DELETE FROM public.group_catechist
     WHERE group_id = ANY (v_graduating_groups);
    GET DIAGNOSTICS v_deleted_links = ROW_COUNT;

    DELETE FROM public.groups
     WHERE id = ANY (v_graduating_groups);
    GET DIAGNOSTICS v_deleted_groups = ROW_COUNT;
  END IF;

  -- ------------------------------------------------------ 4. cadena de nombres
  -- Un único UPDATE con CASE: todas las condiciones se evalúan contra el valor
  -- antiguo, así que no hay efecto cascada entre niveles.
  UPDATE public.groups
     SET name = CASE
                  WHEN name LIKE '1º CONFIRMACIÓN%'
                    THEN '2º CONFIRMACIÓN'    || substring(name from length('1º CONFIRMACIÓN') + 1)
                  WHEN name LIKE '2º PRECONFIRMACIÓN%'
                    THEN '1º CONFIRMACIÓN'    || substring(name from length('2º PRECONFIRMACIÓN') + 1)
                  WHEN name LIKE '1º PRECONFIRMACIÓN%'
                    THEN '2º PRECONFIRMACIÓN' || substring(name from length('1º PRECONFIRMACIÓN') + 1)
                END
   WHERE name LIKE '1º CONFIRMACIÓN%'
      OR name LIKE '2º PRECONFIRMACIÓN%'
      OR name LIKE '1º PRECONFIRMACIÓN%';
  GET DIAGNOSTICS v_renamed = ROW_COUNT;

  -- ------------------------------------------------------- 5. dejar constancia
  -- Dentro de la misma transacción: si la promoción se deshace, el registro
  -- también, y el botón vuelve a estar disponible.
  INSERT INTO public.academic_year_promotions (academic_year_start, summary)
  VALUES (
    v_target_year,
    jsonb_build_object(
      'alumnos_baja',       coalesce(array_length(v_graduating_students, 1), 0),
      'grupos_eliminados',  v_deleted_groups,
      'grupos_renombrados', v_renamed
    )
  );

  -- p_dry_run permite ensayar la operación completa y descartarla: se calcula
  -- todo de verdad y se deshace al lanzar la excepción, que aborta la transacción.
  IF p_dry_run THEN
    RAISE EXCEPTION 'DRY_RUN_OK %', jsonb_build_object(
      'grupos_graduados',   coalesce(array_length(v_graduating_groups, 1), 0),
      'alumnos_baja',       coalesce(array_length(v_graduating_students, 1), 0),
      'asistencias',        v_deleted_attendance,
      'incidencias',        v_deleted_incidents,
      'servicios',          v_deleted_services,
      'grupos_renombrados', v_renamed
    )::text
      USING ERRCODE = 'no_data';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'alumnos_dados_de_baja',   coalesce(array_length(v_graduating_students, 1), 0),
    'ids_alumnos',             to_jsonb(v_graduating_students),
    'grupos_eliminados',       v_deleted_groups,
    'grupos_renombrados',      v_renamed,
    'filas_borradas', jsonb_build_object(
      'student_attendance',                v_deleted_attendance,
      'incidents',                         v_deleted_incidents,
      'mass_services',                     v_deleted_services,
      'parent_email_verification_tokens',  v_deleted_tokens,
      'student_public_access',             v_deleted_access,
      'students',                          v_deleted_students,
      'group_catechist',                   v_deleted_links
    ),
    'parent_email_verifications_desvinculadas', v_cleared_verif
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_incident_profile_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  -- siempre el usuario autenticado
  new.profile_id := auth.uid();
  -- si no te llega registration_date, lo fijamos
  if new.registration_date is null then
    new.registration_date := current_date;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.touch_dni_verification_session()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
